// Minimal reimplementation of Python's argparse behavior for:
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=str, required=True)
// (plus the auto-added -h/--help).
//
// parseArgs(argv) takes process.argv.slice(2) and returns { a: <string> }.
// On a CLI error it writes usage + error to stderr and exits with code 2.
// On -h/--help (or an unambiguous prefix like --he) it writes help to
// stdout and exits with code 0.

function basename(p) {
  const parts = String(p).split('/');
  return parts[parts.length - 1] || 'test15.mjs';
}

function defaultProg() {
  // Mirror argparse's use of basename(sys.argv[0]); for node the script
  // path is process.argv[1].
  if (process.argv && process.argv[1]) return basename(process.argv[1]);
  return 'test15.mjs';
}

function usageLine(prog) {
  return 'usage: ' + prog + ' [-h] --a A\n';
}

function helpText(prog) {
  return usageLine(prog) +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n';
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog));
  process.stderr.write(prog + ': error: ' + message + '\n');
  process.exit(2);
}

// Equivalent of argparse's _negative_number_matcher: ^-\d+$|^-\d*\.\d+$
// (written without RegExp).
function isNegativeNumberLike(s) {
  if (s.length < 2 || s[0] !== '-') return false;
  const rest = s.slice(1);
  let dot = -1;
  for (let i = 0; i < rest.length; i++) {
    const c = rest[i];
    if (c === '.') {
      if (dot !== -1) return false; // more than one dot
      dot = i;
    } else if (c < '0' || c > '9') {
      return false;
    }
  }
  if (dot === -1) return true; // ^-\d+$
  // ^-\d*\.\d+$ : digits after the dot required, before optional
  return dot < rest.length - 1;
}

// Whether a token would be treated by argparse as an option string
// (and therefore not consumed as the value of --a).
function looksLikeOption(s) {
  if (s.length < 2 || s[0] !== '-') return false; // '' and '-' are values
  if (isNegativeNumberLike(s)) return false; // no option looks like a negative number
  return true;
}

export function parseArgs(argv, prog = defaultProg()) {
  const extras = [];
  let a;
  let afterDashDash = false;

  for (let i = 0; i < argv.length; i++) {
    const tok = argv[i];

    if (afterDashDash) {
      extras.push(tok);
      continue;
    }

    if (tok === '--') {
      // Everything from here on is positional; this argparse version
      // keeps the '--' itself among the unrecognized extras.
      afterDashDash = true;
      extras.push('--');
      continue;
    }

    if (tok.startsWith('--a=')) {
      a = tok.slice(4);
      continue;
    }

    if (tok === '--a') {
      const next = i + 1 < argv.length ? argv[i + 1] : undefined;
      if (next === undefined || looksLikeOption(next)) {
        fail(prog, 'argument --a: expected one argument');
      }
      a = next;
      i++;
      continue;
    }

    if (tok === '-h' || tok === '--help') {
      process.stdout.write(helpText(prog));
      process.exit(0);
    }

    // Long-option prefix matching (argparse allow_abbrev, default on).
    // Only '--help' and '--a' exist; '--a' was handled above, so any
    // remaining strict prefix of '--help' longer than '--' selects help.
    if (tok.length > 2 && tok.startsWith('--') && '--help'.startsWith(tok)) {
      process.stdout.write(helpText(prog));
      process.exit(0);
    }

    if (looksLikeOption(tok)) {
      // Unknown optional: collected as an extra (parse_known_args style).
      extras.push(tok);
      continue;
    }

    // Bare positional: this parser defines none, so it is an extra.
    extras.push(tok);
  }

  if (a === undefined) {
    fail(prog, 'the following arguments are required: --a');
  }
  if (extras.length > 0) {
    fail(prog, 'unrecognized arguments: ' + extras.join(' '));
  }
  return { a };
}

import { parseArgs } from './lib/argparse.mjs';
import { safeLoad } from './lib/yamlParser.mjs';
import { dumpFolded } from './lib/yamlEmitter.mjs';

const args = parseArgs(process.argv.slice(2));

let result;
try {
  result = dumpFolded(safeLoad(args.a));
} catch (err) {
  // Python would exit 1 with a traceback on invalid YAML; a short message
  // on stderr plus exit code 1 (and empty stdout) is the required behavior.
  const msg = err && err.message ? err.message : String(err);
  process.stderr.write(msg + '\n');
  process.exit(1);
}

process.stdout.write(result + '\n');

